-- The guide alone starts a trip (guest positions only gate the button),
-- "Confirm meetup" when GPS is too vague, no-shows cancelled and refunded,
-- disputes over a started trip handed to the CMS. Renames 092's per-side
-- start columns to positions. Not re-runnable (the ALTERs); the text upserts.
SET NAMES utf8mb4;

ALTER TABLE `bookings`
  RENAME COLUMN `guest_started_at` TO `guest_located_at`,
  RENAME COLUMN `guest_start_lat` TO `guest_lat`,
  RENAME COLUMN `guest_start_lng` TO `guest_lng`,
  RENAME COLUMN `guide_started_at` TO `guide_located_at`,
  RENAME COLUMN `guide_start_lat` TO `guide_lat`,
  RENAME COLUMN `guide_start_lng` TO `guide_lng`,
  ADD COLUMN `guest_accuracy_m` SMALLINT UNSIGNED NULL AFTER `guest_lng`,
  ADD COLUMN `guide_accuracy_m` SMALLINT UNSIGNED NULL AFTER `guide_lng`,
  ADD COLUMN `guest_meetup_at` DATETIME NULL COMMENT 'confirmed the meetup when GPS could not tell' AFTER `guide_accuracy_m`,
  ADD COLUMN `guide_meetup_at` DATETIME NULL AFTER `guest_meetup_at`,
  ADD COLUMN `disputed_at` DATETIME NULL COMMENT 'a started trip''s cancellation went to our team' AFTER `started_at`,
  ADD COLUMN `dispute_complaint_id` INT UNSIGNED NULL AFTER `disputed_at`;
UPDATE `bookings` SET `guest_located_at` = NULL, `guest_lat` = NULL, `guest_lng` = NULL,
  `guide_located_at` = NULL, `guide_lat` = NULL, `guide_lng` = NULL;

ALTER TABLE `complaints`
  ADD COLUMN `booking_id` INT UNSIGNED NULL COMMENT 'a trip dispute: the booking whose refund staff decide' AFTER `subject_id`,
  ADD KEY `complaints_booking` (`booking_id`);

DELETE FROM `translations` WHERE `key` IN ('common.booking_panel.start_hint', 'common.booking_panel.start_opens', 'common.booking_panel.start_waiting', 'common.booking_panel.start_them', 'common.booking_panel.start_confirmed', 'common.booking_panel.start_locating');

ON DUPLICATE KEY UPDATE `value` = VALUES(`value`);
