INSERT INTO `translations` (`language`, `key`, `value`) VALUES
  ('en', 'common.booking_panel.confirm_meetup', 'Confirm meetup'),
  ('en', 'common.booking_panel.meetup_prompt', 'GPS can’t confirm you’ve met. Tap “Confirm meetup” when you’re together.'),
  ('en', 'common.booking_panel.meetup_waiting', 'Waiting for {name} to confirm the meetup.'),
  ('en', 'common.booking_panel.dispute_open', 'Our team is reviewing this trip and will decide on the refund.'),
  ('en', 'common.booking_panel.dispute_raised', 'Sent to our team — they’ll decide on the refund.'),
  ('en', 'common.booking_panel.approve_refund_note_started', 'Approving refunds them {amount} in full. If you refuse, our team decides.'),
  ('en', 'common.booking_panel.request_cancel_note_started', 'If {name} agrees, you’re refunded {amount} in full. If not, our team decides.'),
  ('en', 'common.booking_panel.guest_pending_note', 'You can withdraw until {name} confirms — you’d be refunded in full. If they don’t answer before the meeting time, it’s cancelled and refunded in full.'),
  ('es', 'common.booking_panel.confirm_meetup', 'Confirmar encuentro'),
  ('es', 'common.booking_panel.meetup_prompt', 'El GPS no puede confirmar que os habéis encontrado. Pulsa «Confirmar encuentro» cuando estéis juntos.'),
  ('es', 'common.booking_panel.meetup_waiting', 'Esperando a que {name} confirme el encuentro.'),
  ('es', 'common.booking_panel.dispute_open', 'Nuestro equipo está revisando este viaje y decidirá sobre el reembolso.'),
  ('es', 'common.booking_panel.dispute_raised', 'Enviado a nuestro equipo: decidirá sobre el reembolso.'),
  ('es', 'common.booking_panel.approve_refund_note_started', 'Si lo apruebas, se le reembolsa {amount} íntegramente. Si lo rechazas, decide nuestro equipo.'),
  ('es', 'common.booking_panel.request_cancel_note_started', 'Si {name} acepta, se te reembolsa {amount} íntegramente. Si no, decide nuestro equipo.'),
  ('es', 'common.booking_panel.guest_pending_note', 'Puedes retirarlo hasta que {name} lo confirme y se te reembolsará íntegramente. Si no responde antes de la hora del encuentro, se cancela y se te reembolsa íntegramente.'),
  ('fr', 'common.booking_panel.confirm_meetup', 'Confirmer la rencontre'),
  ('fr', 'common.booking_panel.meetup_prompt', 'Le GPS ne peut pas confirmer que vous vous êtes retrouvés. Appuyez sur « Confirmer la rencontre » quand vous êtes ensemble.'),
  ('fr', 'common.booking_panel.meetup_waiting', 'En attente de la confirmation de la rencontre par {name}.'),
  ('fr', 'common.booking_panel.dispute_open', 'Notre équipe examine ce voyage et décidera du remboursement.'),
  ('fr', 'common.booking_panel.dispute_raised', 'Transmis à notre équipe, qui décidera du remboursement.'),
  ('fr', 'common.booking_panel.approve_refund_note_started', 'Si vous acceptez, {amount} lui est remboursé intégralement. Si vous refusez, notre équipe décide.'),
  ('fr', 'common.booking_panel.request_cancel_note_started', 'Si {name} accepte, vous êtes remboursé de {amount} intégralement. Sinon, notre équipe décide.'),
  ('fr', 'common.booking_panel.guest_pending_note', 'Vous pouvez retirer votre paiement tant que {name} n’a pas confirmé — vous seriez remboursé intégralement. Sans réponse avant l’heure du rendez-vous, la réservation est annulée et intégralement remboursée.'),
  ('de', 'common.booking_panel.confirm_meetup', 'Treffen bestätigen'),
  ('de', 'common.booking_panel.meetup_prompt', 'Das GPS kann nicht bestätigen, dass ihr euch getroffen habt. Tippe auf „Treffen bestätigen“, wenn ihr zusammen seid.'),
  ('de', 'common.booking_panel.meetup_waiting', 'Wir warten, bis {name} das Treffen bestätigt.'),
  ('de', 'common.booking_panel.dispute_open', 'Unser Team prüft diese Reise und entscheidet über die Erstattung.'),
  ('de', 'common.booking_panel.dispute_raised', 'An unser Team weitergeleitet – es entscheidet über die Erstattung.'),
  ('de', 'common.booking_panel.approve_refund_note_started', 'Wenn du zustimmst, bekommt der Gast {amount} vollständig erstattet. Lehnst du ab, entscheidet unser Team.'),
  ('de', 'common.booking_panel.request_cancel_note_started', 'Stimmt {name} zu, bekommst du {amount} vollständig erstattet. Sonst entscheidet unser Team.'),
  ('de', 'common.booking_panel.guest_pending_note', 'Du kannst zurückziehen, bis {name} bestätigt – dann bekommst du alles erstattet. Kommt bis zum Treffzeitpunkt keine Antwort, wird die Buchung storniert und vollständig erstattet.'),
  ('zh', 'common.booking_panel.confirm_meetup', '确认见面'),
  ('zh', 'common.booking_panel.meetup_prompt', 'GPS 无法确认你们已经见面。在一起时请点击“确认见面”。'),
  ('zh', 'common.booking_panel.meetup_waiting', '正在等待 {name} 确认见面。'),
  ('zh', 'common.booking_panel.dispute_open', '我们的团队正在审核此行程，并将决定退款事宜。'),
  ('zh', 'common.booking_panel.dispute_raised', '已提交给我们的团队，由其决定退款事宜。'),
  ('zh', 'common.booking_panel.approve_refund_note_started', '同意后将向对方全额退还 {amount}。如果拒绝，由我们的团队决定。'),
  ('zh', 'common.booking_panel.request_cancel_note_started', '如果 {name} 同意，你将获得 {amount} 全额退款。否则由我们的团队决定。'),
  ('zh', 'common.booking_panel.guest_pending_note', '在 {name} 确认之前你可以撤回，并获得全额退款。如果对方在见面时间前未回复，预订将被取消并全额退款。'),
  ('it', 'common.booking_panel.confirm_meetup', 'Conferma incontro'),
  ('it', 'common.booking_panel.meetup_prompt', 'Il GPS non riesce a confermare che vi siete incontrati. Tocca «Conferma incontro» quando siete insieme.'),
  ('it', 'common.booking_panel.meetup_waiting', 'In attesa che {name} confermi l’incontro.'),
  ('it', 'common.booking_panel.dispute_open', 'Il nostro team sta esaminando questo viaggio e deciderà sul rimborso.'),
  ('it', 'common.booking_panel.dispute_raised', 'Inviato al nostro team, che deciderà sul rimborso.'),
  ('it', 'common.booking_panel.approve_refund_note_started', 'Approvando, gli rimborsi {amount} per intero. Se rifiuti, decide il nostro team.'),
  ('it', 'common.booking_panel.request_cancel_note_started', 'Se {name} accetta, ti rimborsiamo {amount} per intero. Altrimenti decide il nostro team.'),
  ('it', 'common.booking_panel.guest_pending_note', 'Puoi ritirare il pagamento finché {name} non conferma e avrai un rimborso completo. Se non risponde entro l’orario dell’incontro, la prenotazione viene annullata e rimborsata per intero.'),
  ('ja', 'common.booking_panel.confirm_meetup', '合流を確認'),
  ('ja', 'common.booking_panel.meetup_prompt', 'GPS では合流を確認できません。一緒になったら「合流を確認」をタップしてください。'),
  ('ja', 'common.booking_panel.meetup_waiting', '{name} さんが合流を確認するのを待っています。'),
  ('ja', 'common.booking_panel.dispute_open', 'この旅は当チームが確認中です。返金について判断します。'),
  ('ja', 'common.booking_panel.dispute_raised', '当チームに送信しました。返金について判断します。'),
  ('ja', 'common.booking_panel.approve_refund_note_started', '承認すると {amount} が全額返金されます。拒否した場合は当チームが判断します。'),
  ('ja', 'common.booking_panel.request_cancel_note_started', '{name} さんが同意すると {amount} が全額返金されます。同意しない場合は当チームが判断します。'),
  ('ja', 'common.booking_panel.guest_pending_note', '{name} さんが確認するまでは取り消すことができ、全額返金されます。待ち合わせ時刻までに返答がない場合は予約がキャンセルされ、全額返金されます。'),
  ('ru', 'common.booking_panel.confirm_meetup', 'Подтвердить встречу'),
  ('ru', 'common.booking_panel.meetup_prompt', 'GPS не может подтвердить, что вы встретились. Нажмите «Подтвердить встречу», когда будете вместе.'),
  ('ru', 'common.booking_panel.meetup_waiting', 'Ждём, пока {name} подтвердит встречу.'),
  ('ru', 'common.booking_panel.dispute_open', 'Наша команда рассматривает эту поездку и примет решение о возврате.'),
  ('ru', 'common.booking_panel.dispute_raised', 'Передано нашей команде — она решит вопрос о возврате.'),
  ('ru', 'common.booking_panel.approve_refund_note_started', 'Если вы согласитесь, гостю вернут {amount} полностью. Если откажетесь, решит наша команда.'),
  ('ru', 'common.booking_panel.request_cancel_note_started', 'Если {name} согласится, вам вернут {amount} полностью. Если нет, решит наша команда.'),
  ('ru', 'common.booking_panel.guest_pending_note', 'Вы можете отозвать оплату, пока {name} не подтвердит, — вернём всю сумму. Если ответа не будет до времени встречи, бронирование отменится, а сумма вернётся полностью.'),
  ('ko', 'common.booking_panel.confirm_meetup', '만남 확인'),
  ('ko', 'common.booking_panel.meetup_prompt', 'GPS로는 만났는지 확인할 수 없습니다. 함께 있을 때 “만남 확인”을 눌러 주세요.'),
  ('ko', 'common.booking_panel.meetup_waiting', '{name}님이 만남을 확인하기를 기다리는 중입니다.'),
  ('ko', 'common.booking_panel.dispute_open', '저희 팀이 이 여행을 검토 중이며 환불 여부를 결정합니다.'),
  ('ko', 'common.booking_panel.dispute_raised', '저희 팀에 전달되었습니다. 환불 여부를 결정합니다.'),
  ('ko', 'common.booking_panel.approve_refund_note_started', '승인하면 {amount}이(가) 전액 환불됩니다. 거절하면 저희 팀이 결정합니다.'),
  ('ko', 'common.booking_panel.request_cancel_note_started', '{name}님이 동의하면 {amount}이(가) 전액 환불됩니다. 동의하지 않으면 저희 팀이 결정합니다.'),
  ('ko', 'common.booking_panel.guest_pending_note', '{name}님이 확인하기 전까지 철회할 수 있으며 전액 환불됩니다. 만남 시간 전까지 응답이 없으면 예약이 취소되고 전액 환불됩니다.'),
  ('ar', 'common.booking_panel.confirm_meetup', 'تأكيد اللقاء'),
  ('ar', 'common.booking_panel.meetup_prompt', 'لا يستطيع نظام GPS تأكيد أنكما التقيتما. اضغط «تأكيد اللقاء» عندما تكونان معًا.'),
  ('ar', 'common.booking_panel.meetup_waiting', 'بانتظار أن يؤكد {name} اللقاء.'),
  ('ar', 'common.booking_panel.dispute_open', 'يراجع فريقنا هذه الرحلة وسيقرر بشأن الاسترداد.'),
  ('ar', 'common.booking_panel.dispute_raised', 'أُرسلت إلى فريقنا — سيقرر بشأن الاسترداد.'),
  ('ar', 'common.booking_panel.approve_refund_note_started', 'بالموافقة يُعاد إليه {amount} كاملًا. إذا رفضت، يقرر فريقنا.'),
  ('ar', 'common.booking_panel.request_cancel_note_started', 'إذا وافق {name}، يُعاد إليك {amount} كاملًا. وإلا يقرر فريقنا.'),
  ('ar', 'common.booking_panel.guest_pending_note', 'يمكنك سحب الدفع حتى يؤكد {name} — وستسترد المبلغ كاملًا. إذا لم يصل رد قبل موعد اللقاء، يُلغى الحجز ويُعاد المبلغ كاملًا.'),
  ('tr', 'common.booking_panel.confirm_meetup', 'Buluşmayı onayla'),
  ('tr', 'common.booking_panel.meetup_prompt', 'GPS buluştuğunuzu doğrulayamıyor. Birlikteyken “Buluşmayı onayla”ya dokunun.'),
  ('tr', 'common.booking_panel.meetup_waiting', '{name} buluşmayı onaylaması bekleniyor.'),
  ('tr', 'common.booking_panel.dispute_open', 'Ekibimiz bu geziyi inceliyor ve iade hakkında karar verecek.'),
  ('tr', 'common.booking_panel.dispute_raised', 'Ekibimize gönderildi — iade hakkında karar verecekler.'),
  ('tr', 'common.booking_panel.approve_refund_note_started', 'Onaylarsanız {amount} tamamen iade edilir. Reddederseniz ekibimiz karar verir.'),
  ('tr', 'common.booking_panel.request_cancel_note_started', '{name} kabul ederse {amount} tamamen iade edilir. Etmezse ekibimiz karar verir.'),
  ('tr', 'common.booking_panel.guest_pending_note', '{name} onaylayana kadar geri çekebilirsiniz — tamamı iade edilir. Buluşma saatine kadar yanıt gelmezse rezervasyon iptal edilir ve tamamı iade edilir.'),
  ('pt', 'common.booking_panel.confirm_meetup', 'Confirmar encontro'),
  ('pt', 'common.booking_panel.meetup_prompt', 'O GPS não consegue confirmar que se encontraram. Toque em «Confirmar encontro» quando estiverem juntos.'),
  ('pt', 'common.booking_panel.meetup_waiting', 'A aguardar que {name} confirme o encontro.'),
  ('pt', 'common.booking_panel.dispute_open', 'A nossa equipa está a analisar esta viagem e vai decidir o reembolso.'),
  ('pt', 'common.booking_panel.dispute_raised', 'Enviado à nossa equipa, que vai decidir o reembolso.'),
  ('pt', 'common.booking_panel.approve_refund_note_started', 'Se aprovar, é reembolsado {amount} na totalidade. Se recusar, decide a nossa equipa.'),
  ('pt', 'common.booking_panel.request_cancel_note_started', 'Se {name} aceitar, é reembolsado {amount} na totalidade. Caso contrário, decide a nossa equipa.'),
  ('pt', 'common.booking_panel.guest_pending_note', 'Pode desistir até {name} confirmar; seria reembolsado na totalidade. Se não houver resposta antes da hora do encontro, é cancelada e reembolsada na totalidade.'),
  ('el', 'common.booking_panel.confirm_meetup', 'Επιβεβαίωση συνάντησης'),
  ('el', 'common.booking_panel.meetup_prompt', 'Το GPS δεν μπορεί να επιβεβαιώσει ότι συναντηθήκατε. Πατήστε «Επιβεβαίωση συνάντησης» όταν είστε μαζί.'),
  ('el', 'common.booking_panel.meetup_waiting', 'Αναμονή επιβεβαίωσης της συνάντησης από {name}.'),
  ('el', 'common.booking_panel.dispute_open', 'Η ομάδα μας εξετάζει αυτό το ταξίδι και θα αποφασίσει για την επιστροφή χρημάτων.'),
  ('el', 'common.booking_panel.dispute_raised', 'Στάλθηκε στην ομάδα μας — θα αποφασίσει για την επιστροφή χρημάτων.'),
  ('el', 'common.booking_panel.approve_refund_note_started', 'Αν εγκρίνετε, επιστρέφεται ολόκληρο το ποσό {amount}. Αν αρνηθείτε, αποφασίζει η ομάδα μας.'),
  ('el', 'common.booking_panel.request_cancel_note_started', 'Αν συμφωνήσει {name}, σας επιστρέφεται ολόκληρο το ποσό {amount}. Διαφορετικά αποφασίζει η ομάδα μας.'),
  ('el', 'common.booking_panel.guest_pending_note', 'Μπορείτε να αποσύρετε την πληρωμή μέχρι να επιβεβαιώσει {name} — θα λάβετε πλήρη επιστροφή. Αν δεν υπάρξει απάντηση πριν από την ώρα της συνάντησης, η κράτηση ακυρώνεται και επιστρέφεται ολόκληρο το ποσό.'),
  ('th', 'common.booking_panel.confirm_meetup', 'ยืนยันการพบกัน'),
  ('th', 'common.booking_panel.meetup_prompt', 'GPS ยืนยันไม่ได้ว่าคุณพบกันแล้ว แตะ “ยืนยันการพบกัน” เมื่ออยู่ด้วยกัน'),
  ('th', 'common.booking_panel.meetup_waiting', 'กำลังรอ {name} ยืนยันการพบกัน'),
  ('th', 'common.booking_panel.dispute_open', 'ทีมงานของเรากำลังตรวจสอบทริปนี้และจะตัดสินเรื่องการคืนเงิน'),
  ('th', 'common.booking_panel.dispute_raised', 'ส่งให้ทีมงานของเราแล้ว ทีมงานจะตัดสินเรื่องการคืนเงิน'),
  ('th', 'common.booking_panel.approve_refund_note_started', 'หากอนุมัติ อีกฝ่ายจะได้รับเงินคืน {amount} เต็มจำนวน หากปฏิเสธ ทีมงานของเราจะตัดสิน'),
  ('th', 'common.booking_panel.request_cancel_note_started', 'หาก {name} ตกลง คุณจะได้รับเงินคืน {amount} เต็มจำนวน หากไม่ ทีมงานของเราจะตัดสิน'),
  ('th', 'common.booking_panel.guest_pending_note', 'คุณถอนการชำระเงินได้จนกว่า {name} จะยืนยัน และจะได้รับเงินคืนเต็มจำนวน หากไม่มีการตอบกลับก่อนเวลานัด การจองจะถูกยกเลิกและคืนเงินเต็มจำนวน'),
  ('uk', 'common.booking_panel.confirm_meetup', 'Підтвердити зустріч'),
  ('uk', 'common.booking_panel.meetup_prompt', 'GPS не може підтвердити, що ви зустрілися. Натисніть «Підтвердити зустріч», коли будете разом.'),
  ('uk', 'common.booking_panel.meetup_waiting', 'Чекаємо, поки {name} підтвердить зустріч.'),
  ('uk', 'common.booking_panel.dispute_open', 'Наша команда розглядає цю поїздку й ухвалить рішення щодо повернення коштів.'),
  ('uk', 'common.booking_panel.dispute_raised', 'Передано нашій команді — вона вирішить питання повернення коштів.'),
  ('uk', 'common.booking_panel.approve_refund_note_started', 'Якщо погодитеся, гостю повернуть {amount} повністю. Якщо відмовите, вирішить наша команда.'),
  ('uk', 'common.booking_panel.request_cancel_note_started', 'Якщо {name} погодиться, вам повернуть {amount} повністю. Якщо ні, вирішить наша команда.'),
  ('uk', 'common.booking_panel.guest_pending_note', 'Ви можете відкликати оплату, доки {name} не підтвердить, — повернемо всю суму. Якщо відповіді не буде до часу зустрічі, бронювання скасується, а суму буде повернено повністю.')
